CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, timezone text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE sessions (hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE workspaces (id uuid PRIMARY KEY, name text NOT NULL, owner_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL);
CREATE TABLE memberships (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK (role IN ('owner','editor','viewer')), created_at timestamptz NOT NULL, PRIMARY KEY(workspace_id,user_id));
CREATE INDEX memberships_user ON memberships(user_id);
CREATE TABLE tasks (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), created_by uuid NOT NULL REFERENCES users(id), assignee_id uuid REFERENCES users(id), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('open','done')), due_at timestamptz, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX tasks_workspace_due ON tasks(workspace_id,due_at);
CREATE TABLE notes (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, content text NOT NULL, visibility text NOT NULL CHECK(visibility IN ('private','workspace')), created_at timestamptz NOT NULL);
CREATE TABLE calendar_events (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, attendees jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL, CHECK(ends_at > starts_at));
CREATE INDEX events_workspace_time ON calendar_events(workspace_id,starts_at);
CREATE TABLE comments (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE reminders (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), user_id uuid NOT NULL REFERENCES users(id), object_type text NOT NULL CHECK(object_type IN ('task','event')), object_id uuid NOT NULL, fire_at timestamptz NOT NULL, offset_minutes integer NOT NULL, version integer NOT NULL, status text NOT NULL CHECK(status IN ('pending','queued','cancelled')), created_at timestamptz NOT NULL);
CREATE INDEX reminders_due ON reminders(fire_at) WHERE status='pending';
CREATE INDEX reminders_object ON reminders(object_type,object_id);
CREATE TABLE platform_identities (id uuid PRIMARY KEY, provider text NOT NULL, app_id text NOT NULL, external_id text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL, UNIQUE(provider,app_id,external_id), UNIQUE(provider,app_id,user_id));
CREATE TABLE binding_codes (hash text PRIMARY KEY, provider text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE inbox_events (id uuid PRIMARY KEY, provider text NOT NULL, app_id text NOT NULL, external_id text NOT NULL, sender_id text NOT NULL, text text NOT NULL, processed_at timestamptz, reply_text text NOT NULL DEFAULT '', replied_at timestamptz, created_at timestamptz NOT NULL, UNIQUE(provider,app_id,external_id));
CREATE TABLE outbox_events (id uuid PRIMARY KEY, kind text NOT NULL, ref_id text NOT NULL, published_at timestamptz, created_at timestamptz NOT NULL);
CREATE INDEX outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE notifications (id bigserial PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), kind text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX notifications_user_cursor ON notifications(user_id,id);
CREATE TABLE deliveries (id uuid PRIMARY KEY, notification_id bigint NOT NULL REFERENCES notifications(id), provider text NOT NULL, target text NOT NULL, reminder_id uuid REFERENCES reminders(id), reminder_version integer NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('queued','sending','accepted','retry','failed','unknown','cancelled')), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL, lease_until timestamptz, lease_token text NOT NULL DEFAULT '', last_error text NOT NULL DEFAULT '', provider_message_id text NOT NULL DEFAULT '', created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(notification_id,provider,target));
CREATE INDEX deliveries_due ON deliveries(next_attempt_at) WHERE status IN ('queued','retry','sending');
CREATE TABLE agent_jobs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), request_key text NOT NULL, request_hash text NOT NULL, followup_consumed_at timestamptz, input text NOT NULL, provider text NOT NULL, status text NOT NULL CHECK(status IN ('queued','running','needs_input','succeeded','failed')), result text NOT NULL DEFAULT '', lease_until timestamptz, lease_token text NOT NULL DEFAULT '', attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(user_id,request_key));
CREATE INDEX agent_jobs_pending ON agent_jobs(created_at) WHERE status IN ('queued','running');
